assertions.check:
command -v cc >/dev/null || { echo 'FAIL: no C compiler (cc) on PATH'; exit 1; }
d=$(mktemp -d) && trap 'rm -rf "$d"' 0 || exit 1
printf 'int main(void){return 0;}\n' > "$d/probe.c"
if ! cc "$d/probe.c" -o "$d/probe" 2>/dev/null; then
  for sdk in /Library/Developer/CommandLineTools/SDKs/MacOSX*.sdk; do
    SDKROOT=$sdk cc "$d/probe.c" -o "$d/probe" 2>/dev/null && { SDKROOT=$sdk; export SDKROOT; break; }
  done
fi
srcs=
for f in parsetree/*.c; do
  case $f in */main.c) continue ;; esac
  if grep -Eq '^(static +)?(void|int) *\** *(malloc|calloc|realloc|free|aligned_alloc|posix_memalign) *\(' "$f"; then echo "note: skipping $f (defines an allocator function)"; continue; fi
  srcs="$srcs $f"
done
cat > "$d/zz_count.c" <<'EOF'
#include <stdlib.h>
long eval_allocs, eval_live;
static void *note(void *p) { if (p) { eval_allocs++; eval_live++; } return p; }
void *eval_malloc(size_t n) { return note(malloc(n)); }
void *eval_calloc(size_t a, size_t b) { return note(calloc(a, b)); }
void *eval_aligned_alloc(size_t a, size_t n) { return note(aligned_alloc(a, n)); }
int eval_posix_memalign(void **p, size_t a, size_t n) { int r = posix_memalign(p, a, n); if (!r) note(*p); return r; }
void *eval_realloc(void *q, size_t n) { void *p = realloc(q, n); if (p) { eval_allocs++; if (!q) eval_live++; } return p; }
void eval_free(void *p) { if (p) eval_live--; free(p); }
EOF
cat > "$d/zz_main.c" <<'EOF'
#include "tree.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
extern long eval_allocs, eval_live;
static int bad;
static void one(const char *src) {
    struct tree *t = tree_parse(src);
    if (t == NULL) printf("NULL");
    else { printf("%zu %zu %lu", tree_count(t), tree_height(t), tree_checksum(t)); tree_free(t); }
    printf(" live=%ld\n", eval_live);
    if (eval_live != 0) bad = 1;
}
int main(void) {
    const char *cases[] = {"", " \n\t ", "42", "5 3 8 3", "-9223372036854775808 9223372036854775807 0",
        "1 2 x", "9223372036854775808", "1 2-3", "0x10", "7\n7\n7", NULL};
    for (int i = 0; cases[i]; i++) one(cases[i]);
    size_t n = 200000, len = 0;
    char *big = malloc(n * 13 + 1);
    unsigned long long x = 12345;
    for (size_t i = 0; i < n; i++) { x = (x * 69069 + 1) % 4294967296ULL; len += (size_t)sprintf(big + len, "%lld ", (long long)x - 2147483648LL); }
    long before = eval_allocs;
    struct tree *t = tree_parse(big);
    long used = eval_allocs - before;
    printf("%zu %zu %lu\n", tree_count(t), tree_height(t), tree_checksum(t));
    tree_free(t);
    free(big);
    printf("allocs=%ld live=%ld\n", used, eval_live);
    return bad || eval_live != 0;
}
EOF
flags='-Dmalloc=eval_malloc -Dcalloc=eval_calloc -Drealloc=eval_realloc -Dfree=eval_free -Daligned_alloc=eval_aligned_alloc -Dposix_memalign=eval_posix_memalign'
for f in $srcs "$d/zz_main.c"; do
  cc -O2 -std=c17 -Iparsetree $flags -c "$f" -o "$d/$(basename "$f" .c).o" || exit 1
done
cc -O2 -std=c17 -c "$d/zz_count.c" -o "$d/zz_count.o" && cc "$d"/*.o -o "$d/zz_eval" || exit 1
"$d/zz_eval" > "$d/out.txt"; status=$?
cat "$d/out.txt"
cat > "$d/want.txt" <<'EOF'
0 0 0 live=0
0 0 0 live=0
1 1 42 live=0
4 3 56 live=0
3 3 18446744073709551613 live=0
NULL live=0
NULL live=0
NULL live=0
NULL live=0
3 3 42 live=0
200000 45 14343261929455044142
EOF
grep -v '^allocs=' "$d/out.txt" | diff "$d/want.txt" - && [ "$status" -eq 0 ] || { echo 'FAIL: results differ from the original or memory is still live after tree_free'; exit 1; }

command -v cc >/dev/null || { echo 'FAIL: no C compiler (cc) on PATH'; exit 1; }
